-- Source: EUR-Lex CELLAR ? SPARQL/REST API (53 rows)
-- Generated by gen_mart_models.py

-- DEDUP (2026-08-25 verification): cellar_uri is the true one-row-per-document key,
-- but the raw source carries 13 documents with 2-7 rows apiece (all from a single
-- load run / _SOURCE_RUN_ID). Every column is byte-identical within a group EXCEPT
-- language, which just cycles through re-encodings of the same language code
-- (e.g. 'BG'/'bg'/'bul' all mean Bulgarian; 'CS'/'cs'/'ces'/'cze' all mean Czech) --
-- title/content_url/format_available are blank for every row, so no genuine
-- per-language content exists in this extract. This looks like the loader probing
-- several candidate language-code formats per document against the SPARQL/REST API
-- and getting the same document metadata back each time. Collapse to one row per
-- document, preferring the canonical ISO 639-1 lowercase 2-letter code when present.
with source as (
    select * from {{ source('ripple_raw', 'INTL_EURLEX_CELLAR') }}
    qualify row_number() over (
        partition by CELLAR_URI
        order by case when length(LANGUAGE) = 2 and LANGUAGE = lower(LANGUAGE) then 0 else 1 end,
                 LANGUAGE) = 1
)

select
    CELEX_ID as celex_id,
    ELI_URI as eli_uri,
    ECLI_ID as ecli_id,
    TITLE as title,
    DOCUMENT_TYPE as document_type,
    AUTHOR as author,
    try_to_date(DATE_PUBLISHED) as date_published,
    try_to_date(DATE_OF_DOCUMENT) as date_of_document,
    IN_FORCE as in_force,
    SUBJECT_MATTER as subject_matter,
    COUNTRY as country,
    LANGUAGE as language,
    OJ_SERIES as oj_series,
    OJ_NUMBER as oj_number,
    CONTENT_URL as content_url,
    FORMAT_AVAILABLE as format_available,
    CELLAR_URI as cellar_uri
from source
